// Builds dist/data/vehicle-durability.js: the part health, armor, durability and damage passed to the
// main body of each vehicle stratagem (Exosuits, FRVs, tanks) from the wiki Anatomy tables
// (db/source/wiki_vehicles.json, scripts/fetch-vehicle-pages.mjs) with the site's Korean part names
// (db/source/vehicle_part_korean.json). A part without a Korean name keeps its English one and a page
// without a site stratagem is skipped; both are listed as 'to check' (do not block deploys). Do not edit the output.
// Usage: node scripts/build-vehicle-durability.mjs
import { readFile, writeFile } from 'node:fs/promises';
import { stratagems } from '../dist/core/catalog.js';

const read = async name => JSON.parse(await readFile(new URL(`../db/source/${name}`, import.meta.url), 'utf8'));
const number = text => { const m = /^\s*([\d,]+(?:\.\d+)?)/.exec(String(text ?? '')); return m ? Number(m[1].replace(/,/g, '')) : null; };

export async function buildVehicleDurability() {
  const source = await read('wiki_vehicles.json');
  const korean = (await read('vehicle_part_korean.json')).names;
  const idByTitle = new Map(stratagems.map(item => [item.en, item.id]));
  const toCheck = [];
  const vehicles = {};
  for (const [title, page] of Object.entries(source.pages)) {
    const id = idByTitle.get(title);
    if (!id) { toCheck.push(`${title}: no stratagem with this English name`); continue; }
    vehicles[id] = {
      page: title, revision: page.revision,
      parts: page.rows.map(row => {
        const raw = String(row.part_name ?? '').replace(/<br\s*\/?>/gi, ' ').replace(/\s+/g, ' ').trim();
        const count = Number(/\((\d+)\)$/.exec(raw)?.[1]) || 1;
        const en = raw.replace(/\s*\(\d+\)$/, '');
        if (!korean[en]) toCheck.push(`${title}: no Korean name for part "${en}" (shown in English)`);
        const bleed = /([\d,]+)\s*\[\s*-\s*([\d,]+)\s*\/s\s*\]/.exec(row.bleed ?? '');
        return {
          name: korean[en] ?? en, en, count,
          // health: a number, 'indestructible', or 'main' (the part shares the main body's health).
          health: /indestructible/i.test(row.health ?? '') ? 'indestructible' : /^\s*main\s*$/i.test(row.health ?? '') ? 'main' : number(row.health),
          armor: number(row.av), durability: number(row.durability),
          toMain: number(row.percent_to_main), exdr: number(row.exdr),
          fatal: /^yes/i.test(row.fatal ?? ''), downs: /downs/i.test(row.fatal ?? ''),
          ...(bleed && { bleed: { health: Number(bleed[1].replace(/,/g, '')), perSecond: Number(bleed[2].replace(/,/g, '')) } }),
        };
      }),
    };
  }
  return { vehicles, toCheck, checkedAt: source.retrievedAt };
}

if (import.meta.url === `file:///${process.argv[1].replaceAll('\\', '/').replace(/^\//, '')}`) {
  const data = await buildVehicleDurability();
  await writeFile(new URL('../dist/data/vehicle-durability.js', import.meta.url), `// Generated by scripts/build-vehicle-durability.mjs from the Helldivers Wiki vehicle Anatomy tables
// (CC BY-NC-SA 4.0). Part names are the site's translation. Do not edit.
// toMain: % of part damage also dealt to the main body; exdr: explosive damage resistance %.
export const vehicleDurabilityCheckedAt = ${JSON.stringify(data.checkedAt)};
export const vehicleDurability = ${JSON.stringify(data.vehicles, null, 1)};
`);
  console.log(`${Object.keys(data.vehicles).length} vehicles, ${Object.values(data.vehicles).reduce((n, v) => n + v.parts.length, 0)} parts`);
  if (data.toCheck.length) console.log(`To check:\n  ${data.toCheck.join('\n  ')}`);
}
